#!/usr/bin/env python3
"""Gera o Hangar da Turma (simulador-heli) a partir do Hangar CCOA pessoal, sem os dados pessoais."""
import re, sys
from pathlib import Path

hub = (Path.home() / "Projetos/hangar-ccoa/hub.tpl.html").read_text(encoding="utf-8")
sim = Path.home() / "Projetos/simulador-heli"
L = hub.split("\n")

def bloco(ini, fim):
    """Linhas do hub da que começa com `ini` até antes da que começa com `fim`."""
    a = next(i for i, l in enumerate(L) if l.startswith(ini))
    b = next(i for i, l in enumerate(L) if i > a and l.startswith(fim))
    return "\n".join(L[a:b])

css = hub[hub.index("<style>") + 7: hub.index("</style>")]
css += "\n.quadro{width:100%;border:0;display:block;min-height:70vh;background:transparent}\n.membro{display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-bottom:1px solid var(--linha)}\n.mat-turma{display:inline-flex;align-items:center;gap:4px}\n.mat-turma .sub{font-size:12px}\n.acerto{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid var(--linha);flex-wrap:wrap}\n.acerto:last-child{border-bottom:0}\n.pix-caixa{display:flex;flex-direction:column;gap:6px}\n.pix-form{display:flex;gap:8px;flex-wrap:wrap}\n.pix-form input{flex:1 1 220px}\n.pix-tit{font-weight:700;margin-top:4px}\n.tp-est{padding:10px 0;border-top:1px solid var(--linha);display:flex;flex-direction:column;gap:6px}\n.tp-est:first-of-type{border-top:0;padding-top:0}\n.tp-grupo{padding:6px 0 2px}\n.tp-raw{font-size:12.5px;color:var(--tinta2);word-break:break-word}\n.tp-chips .chip{cursor:default}\n.tp-site{display:flex;flex-direction:column;gap:4px;padding:10px;border:1px solid var(--linha);border-radius:12px}\n.tp-tab td,.tp-tab th{white-space:nowrap;padding:5px 8px}\n.tp-tab tr.tp-al td:first-child{box-shadow:inset 4px 0 0 var(--alerta)}\n.tp-tab tr.tp-pe td:first-child{box-shadow:inset 4px 0 0 var(--perigo)}\n.tp-tab tr.tp-ok td:first-child{box-shadow:inset 4px 0 0 var(--ok)}\n.tp-tab tr.tp-pe{background:var(--perigo-claro)}\n.tp-tab tr.tp-al{background:var(--alerta-claro)}\n.tp-ler summary{cursor:pointer;font-weight:700;font-size:13.5px;color:var(--laranja-esc)}\n.tp-exp{display:grid;grid-template-columns:auto 1fr;gap:5px 10px;font-size:13.5px;margin-top:8px;align-items:start}\n.tp-exp code{font-family:var(--mono);font-size:12.5px;background:var(--chao);padding:2px 6px;border-radius:6px;white-space:nowrap}\n.tp-int{margin-top:10px;font-size:13.5px;background:var(--laranja-claro);border-radius:10px;padding:8px 12px}\n.tp-int ul{margin:4px 0 0;padding-left:18px}\n.tp-int li{margin:3px 0}\n.cp-item{padding:9px 0;border-bottom:1px solid var(--linha)}\n.cp-item:last-child{border-bottom:0}\n.cp-lin{display:flex;align-items:center;gap:10px}\n.cp-txt{flex:1;min-width:0;overflow-wrap:anywhere}\n.cp-check{flex:none;width:30px;height:30px;border-radius:50%;border:2px solid var(--laranja);background:transparent;color:#fff;font-weight:800;padding:0;display:grid;place-items:center}\n.cp-feito .cp-check{background:var(--ok);border-color:var(--ok)}\n.cp-feito .cp-txt b{text-decoration:line-through;color:var(--tinta2)}\n.cp-cat{margin-top:10px}\n.cp-onde{display:flex;flex-direction:column;gap:8px;margin:10px 0 2px 40px;padding:10px 12px;border:1px solid var(--linha);border-radius:12px;background:var(--chao)}\n.cp-onde input{width:100%}\n.cp-onde .linha-acao{flex-wrap:wrap}\n.pv-grade{margin-top:4px}\n.pv-card h3{font-size:18px}\n.pv-lista{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}\n.pv-lista li{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--linha)}\n.pv-lista li:last-child{border-bottom:0}\n.pv-lista li.pv-eu{background:var(--laranja-claro);border-radius:10px;padding-inline:8px}\n.pv-pos{flex:none;width:34px;text-align:center;font-weight:800;font-size:18px}\n.pv-nome{flex:1;min-width:0;display:flex;flex-direction:column;font-weight:700}\n.pv-nome .sub{font-weight:400;font-size:12.5px}\n.pv-val{font-family:var(--display);font-size:24px;color:var(--alerta)}\n.pv-val.ok{color:var(--ok)}\n.pv-val.pe{color:var(--perigo)}\n.goa-cartao{border:2px solid var(--perigo);background:linear-gradient(135deg,var(--perigo-claro),var(--painel) 70%);box-shadow:0 4px 18px -8px var(--perigo)}\n.goa-topo{display:flex;gap:12px;align-items:flex-start}\n.goa-topo h3{font-size:22px;color:var(--perigo)}\n.goa-topo p{margin:4px 0 0}\n.goa-ico{font-size:34px;line-height:1}\n.goa-bt{background:var(--perigo);color:var(--painel);font-size:16px;min-height:46px}\n.goa-docs{border-radius:12px;padding:10px 12px;display:flex;flex-direction:column;gap:6px;font-size:14.5px}\n.goa-docs.pend{background:var(--alerta-claro);border:1.5px solid var(--alerta);color:var(--tinta)}\n.goa-docs.pend>b{color:var(--alerta)}\n.goa-docs.ok{background:var(--ok-claro)}\n.goa-docs.ok>b{color:var(--ok)}\n.goa-docs ul{margin:0;padding-left:20px}\n.dia-perg{display:flex;flex-direction:column;gap:6px;padding-top:8px;border-top:1px dashed var(--linha)}\n.dia-perg input{flex:1 1 200px;min-width:0}\n.dia-res{padding-top:6px;border-top:1px dashed var(--linha);font-size:14px}\n.ct-fatos{display:flex;flex-direction:column;gap:8px}\n.ct-fatos div{display:grid;grid-template-columns:96px minmax(0,1fr);gap:8px;font-size:14.5px}\n.ct-fatos b{color:var(--tinta2);font-size:12.5px;text-transform:uppercase;letter-spacing:.05em}\n.ct-lista{margin:0;padding:0;list-style:none;display:flex;flex-direction:column}\n.ct-lista li{display:flex;flex-direction:column;gap:2px;padding:8px 0;border-bottom:1px solid var(--linha);font-size:14.5px}\n.ct-lista li:last-child{border-bottom:0}\n.ct-ref{font-size:12px;color:var(--tinta3)}\n.ct-ref a{color:var(--tinta3)}\n.ct-horas,.ct-prazos{display:grid;gap:8px}\n.ct-horas div,.ct-prazos div{display:grid;grid-template-columns:120px minmax(0,1fr);gap:10px;align-items:baseline;padding:6px 0;border-bottom:1px solid var(--linha);font-size:14.5px}\n.ct-horas b,.ct-prazos b{font-family:var(--display);font-size:20px;color:var(--laranja-esc)}\n.ct-cobrar{background:var(--ok-claro);border-color:var(--ok)}\n.ct-cobrar h3{color:var(--ok)}\n.ct-cobrar ul{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:4px;font-size:14.5px}\n.ct-semvoo{border:2px solid var(--alerta);box-shadow:inset 4px 0 0 var(--alerta)}\n.ct-sv{display:flex;flex-direction:column}\n.ct-sv-item{display:flex;flex-direction:column;gap:4px;padding:10px 0;border-bottom:1px solid var(--linha);font-size:14.5px}\n.ct-sv-item:last-child{border-bottom:0}\n.ct-sv-item b{font-size:16px}\n.ct-tag{align-self:flex-start;font-size:11.5px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;border-radius:999px;padding:2px 10px}\n.ct-tag.sim{background:var(--ok-claro);color:var(--ok)}\n.ct-tag.nao{background:var(--perigo-claro);color:var(--perigo)}\n.ct-tag.info{background:var(--laranja-claro);color:var(--laranja-esc)}\n.ct-refs{display:flex;flex-wrap:wrap;gap:2px 6px}\n.ct-passos{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:6px;font-size:14.5px}\n.ct-mod summary{cursor:pointer;font-weight:700;color:var(--laranja-esc)}\n.ct-mod textarea{width:100%;margin:8px 0;font-size:13.5px;line-height:1.4}\n@media(max-width:520px){.ct-horas div,.ct-prazos div,.ct-fatos div{grid-template-columns:minmax(0,1fr)}}\n.goa-como summary{cursor:pointer;font-weight:700;color:var(--perigo)}\n.goa-como ol{margin:8px 0;padding-left:20px;display:flex;flex-direction:column;gap:6px;font-size:14.5px}\n.pv-alerta{background:var(--perigo-claro);color:var(--perigo);border:1.5px solid var(--perigo);border-radius:10px;padding:8px 12px;font-weight:700;font-size:14.5px}\n.pv-alerta.forte{font-size:16px;padding:12px 14px}\n.pv-abaixo{color:var(--perigo);font-weight:700}\ndiv.pv-alt{display:flex;align-items:center;gap:6px;border-radius:10px}\n.pv-prog{display:flex;justify-content:space-between;gap:10px;font-size:14px;color:var(--tinta2);margin:6px 0 4px;flex-wrap:wrap}\n.pv-q{margin-top:10px}\n.pv-tema{font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--laranja-esc)}\n.pv-enun{font-size:18px;font-weight:600;margin:0;line-height:1.4;overflow-wrap:anywhere}\n.pv-alts{display:flex;flex-direction:column;gap:8px}\n.pv-alt{justify-content:flex-start;text-align:left;background:var(--painel);border:1.5px solid var(--linha);font-weight:500;line-height:1.35;padding:10px 12px;min-height:48px;width:100%}\n.pv-alt b{flex:none;display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--chao);font-size:14px}\n.pv-alt span{flex:1;min-width:0;overflow-wrap:anywhere}\n.pv-alt:not(:disabled):hover{border-color:var(--laranja)}\n.pv-alt:disabled{cursor:default;opacity:1;color:var(--tinta)}\n.pv-alt.certa{border-color:var(--ok);background:var(--ok-claro)}\n.pv-alt.certa b{background:var(--ok);color:var(--painel)}\n.pv-alt.errada{border-color:var(--perigo);background:var(--perigo-claro)}\n.pv-alt.errada b{background:var(--perigo);color:var(--painel)}\n.pv-alt.apagada{opacity:.55}\n.pv-res{border-radius:12px;padding:12px 14px;display:flex;flex-direction:column;gap:6px}\n.pv-res p{margin:0}\n.pv-res.ok{background:var(--ok-claro)}\n.pv-res.ok>b{color:var(--ok)}\n.pv-res.pe{background:var(--perigo-claro)}\n.pv-res.pe>b:first-child{color:var(--perigo)}\n.pv-res summary,.pv-rev summary{cursor:pointer;font-weight:700;color:var(--laranja-esc)}\n.pv-fonte{display:flex;flex-direction:column;gap:6px;margin-top:4px;padding-top:8px;border-top:1px solid var(--linha)}\n.pv-fonte blockquote{margin:0;padding:6px 10px;border-left:3px solid var(--laranja);background:var(--painel);border-radius:0 8px 8px 0;font-size:14px;color:var(--tinta2);overflow-wrap:anywhere}\n.pv-fonte .linha-acao{flex-wrap:wrap}\n.pv-fonte .btn{max-width:100%;white-space:normal;text-align:left}\n.pv-seg{justify-content:flex-end}\n.pv-placar{flex-direction:row;align-items:center;gap:16px;flex-wrap:wrap}\n.pv-placar.ok{border-color:var(--ok);box-shadow:inset 4px 0 0 var(--ok)}\n.pv-placar.pe{border-color:var(--perigo);box-shadow:inset 4px 0 0 var(--perigo)}\n.pv-nota{font-family:var(--display);font-size:56px;font-weight:700;line-height:1}\n.pv-placar.ok .pv-nota{color:var(--ok)}\n.pv-placar.pe .pv-nota{color:var(--perigo)}\n.pv-rev{padding:8px 0;border-bottom:1px solid var(--linha)}\n.pv-rev p{margin:6px 0}\n@media(max-width:520px){.cp-onde{margin-left:0}.cp-lin{flex-wrap:wrap}.cp-txt{flex-basis:calc(100% - 80px)}}\n"
(sim / "src/hangar").mkdir(exist_ok=True)
(sim / "src/hangar/hangar.css").write_text(css.strip() + "\n", encoding="utf-8")

revisao = bloco("revisao(){", "treino(){")
treino = bloco("treino(){", "materiais(){")
# caixa alta automática no METAR colado (máscara do src/entrada.js, que o hub pessoal não tem)
treino = treino.replace('<textarea id="mtIn" class="mono" aria-label="METAR">', '<textarea id="mtIn" class="mono" data-m="maiusculo" maxlength="400" aria-label="METAR">')
assert 'data-m="maiusculo"' in treino
acessos = bloco("acessos(){", "};")
# fora do material da turma: CANAC, cofre de senhas e atalhos pessoais
acessos = re.sub(r'\s*<p class="sub">CANAC.*?</p>', "", acessos)
acessos = re.sub(r'\s*<div class="caixa"><h3>Meus atalhos</h3>.*?</div></div>`;', "\n  `;", acessos, flags=re.S)
metar = bloco("function decodificarMetar(txt){", "// ---------- ligações ----------")
sn = next(l for l in L if l.startswith("const SN = "))
ligar_treino = next(i for i, l in enumerate(L) if l.startswith("  treino(){ $('#mtBtn')"))
ligar_treino = "\n".join(L[ligar_treino:ligar_treino + 5])
esquilo = bloco("  { dia: 'esquilo'", "];")
ckdados = bloco("// ---------- checklists ----------", "// ---------- fim checklists ----------")
checklists = bloco("checklists(){", "revisao(){")
ligar_ck = bloco("  checklists(c){", "  treino(){ $('#mtBtn')")
for nome, txt in [("acessos", acessos), ("ligar", ligar_treino)]:
    for proibido in ["464823", "1Password", "NOTION", "PAINEL", "GDAF", "53357"]:
        assert proibido not in txt, (nome, proibido)

modelo = (Path(sys.argv[1])).read_text(encoding="utf-8")
saida = (modelo.replace("/*@SN@*/", sn).replace("/*@ESQUILO@*/", esquilo)
         .replace("/*@REVISAO@*/", revisao).replace("/*@TREINO@*/", treino).replace("/*@ACESSOS@*/", acessos)
         .replace("/*@METAR@*/", metar).replace("/*@LIGAR_TREINO@*/", ligar_treino)
         .replace("/*@CKDADOS@*/", ckdados).replace("/*@CHECKLISTS@*/", checklists).replace("/*@LIGAR_CK@*/", ligar_ck))
assert "/*@" not in saida
(sim / "src/hangar/main.js").write_text(saida, encoding="utf-8")
print("ok", len(saida))
